mapper.select:
SELECT ID , PHARMACY_NAME , LATITUDE, LONGITUDE, PHONE, ADDRESS FROM PHARMACY where
id in( select pharmacy_id from pharmacy_stock where medicine_id in( select id from medicine where product_name like '%' || #{keyword} || '%' and drug_type = '전문의약품' and ingredient_code is not null) ) AND
LATITUDE BETWEEN #{minLat} AND #{maxLat} AND LONGITUDE BETWEEN #{minLon} AND #{maxLon}
